pub(crate) const STYLES: &str = r#"
.df-character-display .character-hero{padding-top:55px;text-align:center}.df-character-display .character-description{margin:0 auto;max-width:760px}.df-character-display h1{font-size:clamp(42px,5vw,82px)}.df-character-display .display-report{display:flex;align-items:center;justify-content:center;gap:22px;margin-top:30px}.df-character-display .display-readiness{font:12px/1.6 system-ui,sans-serif;color:#ebcd91;border:1px solid #ad925d66;border-radius:3px;background:#0a1425bb;padding:9px 16px;margin:0}.df-character-display .display-progress{font:13px/1.7 system-ui,sans-serif;color:#b6cad7;margin:0}.df-character-display .display-notice{font:13px/1.7 system-ui,sans-serif;color:#c8d2dc;min-height:24px;max-width:800px;margin:20px auto 0}.df-character-display[data-connection=offline] .display-notice,.df-character-display[data-connection=reconnecting] .display-notice{color:#ecc296}.df-character-display .display-roster{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(230px,100%),1fr));gap:24px;width:min(1380px,92%);margin:0 auto 40px;align-items:stretch}.df-character-display .display-member{border:1px solid #ad925d55;border-radius:4px;background:linear-gradient(140deg,#0c1721ef,#08101cf5);padding:24px;text-align:center;box-shadow:0 15px 40px #0003}.df-character-display .display-portrait{height:250px;margin:0 0 24px}.df-character-display .display-member-name{font-size:28px;color:#f1dfbd;margin:0 0 15px}.df-character-display .display-member-readiness{font:11px/1.6 system-ui,sans-serif;letter-spacing:.5px;color:#aebecd;margin:0 0 15px}.df-character-display .display-member-progress{font:12px/1.7 system-ui,sans-serif;color:#b6cad7;margin:0;padding-top:15px;border-top:1px solid #ad925d33}.df-character-display .display-member[data-readiness=ready],.df-character-display .display-member[data-readiness=locked]{border-color:#82b79b88}.df-character-display .display-member[data-readiness=ready] .display-member-readiness,.df-character-display .display-member[data-readiness=locked] .display-member-readiness{color:#b5ddc2}.df-character-display .display-host-offers{width:min(1000px,92%);margin:0 auto 30px;display:flex;justify-content:center;flex-wrap:wrap;gap:12px}.df-character-display .display-host-offers button{width:auto;min-width:220px}.df-character-display .display-fixture-controls{width:min(1380px,92%);margin:0 auto 24px;display:flex;gap:10px;flex-wrap:wrap}.df-character-display .display-fixture-controls button{width:auto}.df-character-display .display-fixture-output{width:min(1380px,92%);margin:0 auto 24px;font:12px/1.7 system-ui,sans-serif;color:#b9c8d6}
@media(min-width:1800px){.df-character-display .character-hero{padding-top:80px}.df-character-display .display-roster{gap:30px}.df-character-display .display-member{padding:30px}.df-character-display .display-portrait{height:290px}}
@media(max-width:700px){.df-character-display .character-hero{padding-top:35px}.df-character-display .display-report{flex-direction:column;gap:12px}.df-character-display .display-roster{grid-template-columns:1fr;width:90%;gap:18px}.df-character-display .display-member{padding:22px}.df-character-display .display-portrait{height:230px;max-width:330px;margin:0 auto 22px}.df-character-display .display-host-offers button{width:100%;min-width:0}.df-character-display .display-fixture-controls{width:90%}.df-character-display .display-fixture-controls button{flex:1 1 150px}}
"#;
